CREATE DATABASE IF NOT EXISTS `db_deteksi_daun` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `db_deteksi_daun`;
DROP TABLE IF EXISTS `history_deteksi`;
DROP TABLE IF EXISTS `users`;
DROP TABLE IF EXISTS `penyakit`;
CREATE TABLE `users` (`id_user` INT(11) NOT NULL AUTO_INCREMENT,`username` VARCHAR(50) NOT NULL UNIQUE,`password` VARCHAR(255) NOT NULL,`nama_lengkap` VARCHAR(50) NOT NULL,`role` ENUM('Admin','Petugas') NOT NULL DEFAULT 'Petugas',`created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id_user`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `penyakit` (`id_penyakit` INT(11) NOT NULL AUTO_INCREMENT,`nama_penyakit` VARCHAR(50) NOT NULL UNIQUE,`deskripsi` TEXT NOT NULL,`solusi` TEXT NOT NULL,PRIMARY KEY (`id_penyakit`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `history_deteksi` (`id_deteksi` INT(11) NOT NULL AUTO_INCREMENT,`id_user` INT(11) NOT NULL,`id_penyakit` INT(11) NOT NULL,`nama_file` VARCHAR(100) NOT NULL,`akurasi` FLOAT NOT NULL DEFAULT 0,`tgl_deteksi` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id_deteksi`),CONSTRAINT `fk_deteksi_user` FOREIGN KEY (`id_user`) REFERENCES `users`(`id_user`) ON DELETE CASCADE,CONSTRAINT `fk_deteksi_penyakit` FOREIGN KEY (`id_penyakit`) REFERENCES `penyakit`(`id_penyakit`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO `users` (`username`,`password`,`nama_lengkap`,`role`) VALUES ('admin','$2y$12$F99Gs9d/jk3xia2K68ybz.9wR7ird58ST6lr9QpAsR9XgcjGx1Lr.','Administrator','Admin'),('petugas1','$2y$12$Ek3AwFLVEN8DeUMPkSJ2/uDJn0gdrMOlFYe9L1npcpCwpsSu/GDVi','Budi Santoso','Petugas');
INSERT INTO `penyakit` (`nama_penyakit`,`deskripsi`,`solusi`) VALUES ('Canker','Citrus Canker disebabkan oleh bakteri Xanthomonas citri subsp. citri. Gejala berupa bercak-bercak kecil berwarna coklat yang menonjol (raised lesion) dengan tepi berair dan dikelilingi lingkaran kuning (halo) pada daun, buah, dan ranting muda.','Penanganan:\n1. Pangkas dan musnahkan bagian tanaman yang terinfeksi.\n2. Aplikasikan bakterisida berbahan aktif tembaga hidroksida (Kocide 2000) dosis 2-3 g/L setiap 14 hari.\n3. Semprot Streptomycin sulfat 0.5 g/L sebagai alternatif saat cuaca lembab.\n4. Desinfeksi alat potong dengan alkohol 70%.\n5. Hindari pemangkasan saat daun basah.'),('HLB','Huanglongbing (HLB) atau Citrus Greening disebabkan bakteri Candidatus Liberibacter asiaticus yang ditularkan kutu loncat jeruk (Diaphorina citri). Gejala: daun menguning tidak simetris (blotchy mottle), tulang daun tetap hijau sedangkan helai daun menguning, buah kecil asimetris dan pahit.','Penanganan:\n1. Tidak ada obat kuratif - cabut dan musnahkan tanaman terinfeksi.\n2. Kendalikan vektor Diaphorina citri dengan Imidakloprid 0.5 ml/L.\n3. Pasang perangkap kuning (yellow sticky trap).\n4. Gunakan bibit bersertifikat bebas HLB.\n5. Inspeksi rutin setiap 2 minggu.'),('Greasy Spot','Greasy Spot disebabkan jamur Mycosphaerella citri. Gejala: bercak berminyak kuning transparan di permukaan bawah daun yang berkembang menjadi bercak coklat-hitam menonjol. Menyebabkan daun gugur prematur.','Penanganan:\n1. Kumpulkan dan musnahkan daun gugur sumber inokulum.\n2. Aplikasikan fungisida minyak petroleum 1-2% pada awal musim hujan.\n3. Semprot tembaga oksiklorida (Cupravit) 3 g/L.\n4. Alternatif: Mancozeb 3 g/L setiap 21 hari.\n5. Perbaiki drainase dan pemangkasan sirkulasi udara.'),('Melanose','Melanose disebabkan jamur Diaporthe citri. Gejala: bintik-bintik kecil coklat-kehitaman, kasar seperti amplas pada daun muda, ranting, dan kulit buah.','Penanganan:\n1. Pangkas dan bakar ranting mati sumber spora.\n2. Aplikasikan tembaga hidroksida 2.5 g/L saat pucuk baru.\n3. Semprot Mancozeb 80WP 3 g/L sebagai protektan.\n4. Ulangi setiap 10-14 hari saat musim hujan.\n5. Pemupukan NPK berimbang (16:16:16).'),('Sooty Mold','Embun Jelaga (Sooty Mold) adalah pertumbuhan jamur hitam superfisial yang tumbuh di atas embun madu dari serangga penghisap (kutu daun, kutu putih, kutu sisik). Menghalangi fotosintesis.','Penanganan:\n1. Kendalikan serangga penghasil embun madu: Imidakloprid 0.5 ml/L.\n2. Cuci daun dengan larutan sabun deterjen ringan 2 ml/L.\n3. Tingkatkan populasi musuh alami.\n4. Pangkas cabang rapat untuk sirkulasi udara.\n5. Monitoring keberadaan serangga tiap minggu.'),('Healthy','Daun dalam kondisi sehat. Tidak ditemukan gejala penyakit. Warna daun hijau merata, permukaan halus, tulang daun normal.','Rekomendasi Perawatan:\n1. Lanjutkan pemupukan NPK (16:16:16) 200-300 g/pohon per 3 bulan.\n2. Berikan pupuk organik 10-15 kg/pohon per tahun.\n3. Penyiraman teratur saat kemarau.\n4. Monitoring rutin setiap 2 minggu.\n5. Jaga kebersihan area dari gulma.');
